SELECT internal_id AS internalId, id, area_nm AS name, area_desc AS description, raw_address AS address, area_se AS type, latitude, longitude, ST_Distance(location, ST_MakePoint(#{lng}, #{lat})::geography) AS distanceMeter, fclty_knd AS imageUrl, status FROM smoking_areas
status != 'CLOSED' AND ST_DWithin(location, ST_MakePoint(#{lng}, #{lat})::geography, COALESCE(#{radius}, 1000))
AND area_se = #{type}
AND status = #{status}
ORDER BY distanceMeter ASC
